import currency

supply = Variable()
balances = Hash(default_value=0)
owner = Variable()
contract_owner = Variable()

@construct
def seed(owner_this: str, contract_owner_this: str, amount=2500):
    balances[owner_this] = amount
    supply.set(amount)
    owner.set(owner_this)
    contract_owner.set(contract_owner_this)

@export
def transfer(amount: float, to: str):
    sender = ctx.caller
    assert balances[sender] >= amount, 'Not enough coins to send!'

    balances[sender] -= amount
    balances[to] += amount

@export
def balance_of(account: str):
    return balances[account]

@export
def total_supply():
    return supply.get()

@export
def allowance(main: str, spender: str):
    return balances[main, spender]

@export
def approve(amount: float, to: str):
    sender = ctx.caller
    balances[sender, to] += amount
    return balances[sender, to]


@export
def transfer_from(amount: float, to: str, main_account: str):
    sender = ctx.caller

    assert balances[main_account, sender] >= amount, 'Not enough coins approved to send! You have {} and are trying to spend {}'\
        .format(balances[main_account, sender], amount)
    assert balances[main_account] >= amount, 'Not enough coins to send!'

    balances[main_account, sender] -= amount
    balances[main_account] -= amount

    balances[to] += amount

@export
def transfer_from_currency(reward: float, amount: float, account: str):
    assert ctx.caller == contract_owner.get()
    assert amount > 0, 'Invalid amount!'
    assert reward > 0, 'Invalid reward!'

    currency.transfer_from(reward, account, ctx.this)
    balances[account] -= amount
    supply.set(supply.get() - amount)

@export
def redeem(amount: float):
    assert balances[ctx.caller] >= amount, 'Not enough tokens to redeem!'
    assert amount > 0, 'Invalid amount!'
  
    share = amount / supply.get()
    reward = share * currency.balance_of(ctx.this)

    if reward > 0:
        currency.transfer(reward, ctx.caller)
        balances[ctx.caller] -= amount
        supply.set(supply.get() - amount)



@export
def change_ownership(new_owner: str):
    assert ctx.caller == owner.get(), 'Only the owner can change ownership!'

    owner.set(new_owner)

@export
def change_contracthip(new_contract: str):
    assert ctx.caller == owner.get(), 'Only the owner can change ownership!'

    contract_owner.set(new_contract)
